// A circle recovered from a general equation by completing the square.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(300,300);
draw(circle((-2,3),sqrt(13)));
draw((-5.2,0)--(0.6,0),Arrow);
draw((0,-4.2)--(0,5.2),Arrow);
dot((-2,3), black+3pt);
dot((0,0), black+2.5pt);
label("center $(-2,3)$",(-2,3.5),NE);
label("through the origin",(-2.2,-0.4),SW);
label("$(x+2)^{2}+(y-3)^{2}=13$",(-1.6,-4.2),S);

// A degenerate conic: the parallel lines x+y=1 and x+y=3.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(300,300);
draw((-3.2,4.2)--(3.2,-2.2));
draw((-1.2,4.2)--(5.2,-2.2));
label("$x+y=3$",(-1.6,2.4),NW);
label("$x+y=1$",(3.4,-0.6),SE);
label("the equation is $(x+y-1)(x+y-3)=0$",(1.0,3.6),N);

// The ellipse 9x^2 + 25y^2 = 225 with its two semiaxes marked.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
import graph;
size(300,180);
draw(ellipse((0,0),5,3));
draw((-5,0)--(5,0),Arrow);
draw((0,-3)--(0,3),Arrow);
dot((5,0), black+2.5pt);
dot((0,3), black+2.5pt);
label("$a=5$",(2.5,0.35),N);
label("$b=3$",(0.35,1.5),E);
label("area $=\pi ab$",(0,-3.6),S);

// The upward parabola y = 2(x-2)^2 - 2 with its focus and directrix.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
import graph;
size(300,300);
draw(graph(new real(real t){return 2*(t-2)*(t-2)-2;},-1.4,5.4));
draw((-1.4,-1.875)--(5.4,-1.875),dashed);
dot((2,-2), black+2.5pt);
dot((2,-1.875), black+3pt);
label("vertex $(2,-2)$",(1.7,-2.35),SW);
label("focus",(2.3,-1.875),NE);
label("directrix",(4.6,-1.875),NE);
